const managerHtml = manager
  ? '<p>Chào <strong>' + esc(manager.fullName) + '</strong>,</p><p>Nhân viên <strong>' + esc(employee.fullName) + '</strong> đang có khóa học bắt buộc <strong>' + esc(course.title) + '</strong> ' + dueLabel + '; tiến độ hiện tại là <strong>' + item.progressPercent + '%</strong>.</p><p>Vui lòng hỗ trợ đôn đốc nhân viên hoàn thành.</p>'
  : '';
const managerLabel = item.managerSource === 'DEPARTMENT' ? 'Quản lý phòng ban' : 'Quản lý trực tiếp';
const telegramText = [
  '📚 <b>NHẮC TIẾN ĐỘ ĐÀO TẠO</b>',
  '',
  'Nhân viên: <b>' + esc(employee.fullName) + '</b>',
  'Khóa học: <b>' + esc(course.title) + '</b>',
  'Tiến độ: <b>' + item.progressPercent + '%</b>',
  'Hạn: <b>' + dueLabel + '</b>',
  manager
    ? managerLabel + ': <b>' + esc(manager.fullName) + '</b>'
    : '⚠️ Chưa khai báo quản lý cho nhân viên'
